<script setup lang="ts">
import { ref, onMounted, onBeforeUnmount } from 'vue';
import { useTheme } from './lib/theme';
import { getStatus, submit, getJob, cancel, getResult, imageRequest, enhance, type Role } from './lib/imagestudio-api';
import { createJobController, type JobView } from './lib/job-controller';
import { createEnhancementController, type EnhancementView } from './lib/enhancement-controller';
import StatusChip from './components/StatusChip.vue';
import { listImages, saveImage, deleteImage, exportGallery, importGallery, DuplicateGalleryImportError, referenceData, downloadBlob, type GalleryItem } from './lib/gallery';
const { toggleTheme, resolvedTheme } = useTheme();
const role = ref<Role>('create'), prompt = ref(''), reference = ref<string | null>(null);
const status = ref('Checking application status…'), available = ref(false), isMock = ref(false), error = ref(''), resultUrl = ref('');
const view = ref<JobView>({job:null,busy:false,error:'',retry:null,phase:'idle'});
let active = true, preview = '', previewBlob:Blob | null = null, previewItem:GalleryItem | null = null, pendingMeta:{role:Role;prompt:string;mock:boolean;referenceId?:string;referenceImage?:string} | null = null, referenceId:string | undefined;
const referenceVersion=ref(0), previewReference=ref<string | null>(null), enhancement=ref<EnhancementView>({busy:false,suggestion:'',original:null,error:'',accepted:false});
const enhancer=createEnhancementController((text,kind,signal)=>enhance(text,kind,signal), state=>{enhancement.value=state}, text=>{prompt.value=text});
function switchRole(next:Role){if(view.value.busy)return;enhancer.reset();role.value=next;}
function promptChanged(){if(enhancement.value.busy || !enhancement.value.accepted)enhancer.reset();}
function clearReference(){reference.value=null;referenceId=undefined;referenceVersion.value++;}
const gallery = ref<Array<{item:GalleryItem;url:string}>>([]), galleryError=ref(''), galleryMessage=ref(''), saving=ref(false), saved=ref(false), storageReady=ref(false), importing=ref(false);
function revokeGallery() { for(const entry of gallery.value) URL.revokeObjectURL(entry.url); gallery.value=[]; }
async function refreshGallery() { try { const items=await listImages(); if(!active)return; const rows=items.sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).map(item=>({item,url:URL.createObjectURL(item.blob)})); revokeGallery();gallery.value=rows;storageReady.value=true;galleryError.value=''; } catch(e) { if(!active)return;storageReady.value=false;galleryError.value=e instanceof Error ? e.message : 'Browser storage unavailable.'; } }
async function savePreview() { if(!previewItem || !previewBlob || saving.value || saved.value || view.value.busy)return; const item=previewItem; saving.value=true;galleryError.value='';try{await saveImage(item);if(!active)return;if(previewItem?.id===item.id)saved.value=true;galleryMessage.value='Image saved on this browser.';await refreshGallery();}catch(e){if(active)galleryError.value=e instanceof Error?e.message:'Save failed.';}finally{saving.value=false;} }
async function removeImage(item:GalleryItem) { if(!window.confirm('Delete this saved image from this browser? Other images retain its ID as historical lineage.'))return;try{await deleteImage(item.id);if(previewItem?.id===item.id)saved.value=false;galleryMessage.value='Image deleted.';await refreshGallery();}catch(e){galleryError.value=e instanceof Error?e.message:'Delete failed.';} }
function downloadImage(item:GalleryItem) {const ext=item.mime==='image/png'?'png':item.mime==='image/jpeg'?'jpg':'webp';downloadBlob(item.blob,`imagestudio-${item.id}.${ext}`);}
async function reuseImage(item:GalleryItem) { try {reference.value=await referenceData(item);referenceId=item.id;switchRole('edit');galleryMessage.value='Saved image selected as the Edit reference.';}catch(e){galleryError.value=e instanceof Error?e.message:'Reference could not be loaded.';} }
async function exportImages() {try{const blob=await exportGallery(gallery.value.map(x=>x.item));downloadBlob(blob,'imagestudio-gallery-v1.json');galleryMessage.value='Gallery export prepared.';}catch(e){galleryError.value=e instanceof Error?e.message:'Export failed.';} }
async function importImages(event:Event) {const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file||importing.value)return;importing.value=true;galleryError.value='';try{const n=await importGallery(file);galleryMessage.value=`Imported ${n} images.`;await refreshGallery();}catch(e){if(e instanceof DuplicateGalleryImportError)console.warn('Gallery import rejected because an image ID already exists.',e.cause);galleryError.value=e instanceof Error?e.message:'Import failed; existing images were not overwritten.';}finally{importing.value=false;} }

function clearPreview() { if (preview) URL.revokeObjectURL(preview); preview = ''; resultUrl.value = ''; }
const controller = createJobController({submit,getJob,cancel,getResult}, state => { view.value = state; }, blob => { clearPreview(); previewReference.value=pendingMeta?.role==='edit' ? pendingMeta.referenceImage || null : null; previewBlob=blob; previewItem={id:crypto.randomUUID(),blob,mime:blob.type,size:blob.size,createdAt:new Date().toISOString(),role:pendingMeta?.role || 'create',mock:pendingMeta?.mock ?? false,...(pendingMeta?.prompt?{prompt:pendingMeta.prompt}:{}),...(pendingMeta?.referenceId?{referenceId:pendingMeta.referenceId}:{})}; saved.value=false;preview = URL.createObjectURL(blob); resultUrl.value = preview; });
async function refreshStatus() { error.value = ''; try { const s = await getStatus(); if (!active) return; available.value = s.available; isMock.value = s.mock; status.value = s.message || (s.available ? 'Application API available' : 'Application API unavailable'); } catch (e) { if (!active) return; available.value = false; status.value = 'Application API unavailable'; error.value = e instanceof Error ? e.message : 'Status failed'; } }
function selectReference(event: Event) { const input = event.target as HTMLInputElement; const file = input.files?.[0]; reference.value = null; referenceId=undefined; error.value = ''; if (!file) return; if (!['image/png','image/jpeg','image/webp'].includes(file.type) || file.size > 5*1024*1024) { error.value = 'Choose one PNG, JPEG or WebP image no larger than 5 MiB.'; input.value = ''; return; } const reader = new FileReader(); reader.onload = () => { if (typeof reader.result === 'string') reference.value = reader.result; }; reader.onerror = () => { error.value = 'Could not read reference image.'; }; reader.readAsDataURL(file); }
async function generate() { error.value = ''; if(view.value.busy)return; const request = role.value === 'create' ? {role:'create' as const,prompt:prompt.value} : {role:'edit' as const,prompt:prompt.value,references:reference.value ? [reference.value] : []}; try {imageRequest(request);}catch(e){error.value=e instanceof Error?e.message:'Invalid request';return;} pendingMeta={role:role.value,prompt:prompt.value.trim(),mock:isMock.value,...(role.value==='edit'&&reference.value?{referenceImage:reference.value}:{}),...(role.value==='edit'&&referenceId?{referenceId}:{})}; await controller.start(request); }
onMounted(() => { void refreshStatus(); void refreshGallery(); }); onBeforeUnmount(() => { active = false; controller.dispose(); enhancer.dispose(); clearPreview(); revokeGallery(); });
</script>
<template>
  <main class="studio-shell studio-frame">
    <header class="studio-header"><div class="studio-brand"><span class="brand-mark" aria-hidden="true">✦</span><div><strong>ImageStudio</strong><small>YOUR PRIVATE CREATIVE SPACE</small></div></div><div class="studio-header__actions"><StatusChip :status="available ? 'online' : 'offline'" :label="available ? 'Connected' : 'Unavailable'"/><button class="btn-ghost" type="button" @click="toggleTheme" :aria-label="`Switch theme, current ${resolvedTheme}`">{{ resolvedTheme === 'dark' ? '☀' : '☾' }}</button></div></header>
    <div v-if="isMock" class="mock-banner" role="status">Synthetic mock · No image inference</div>
    <div v-if="!available" class="notice" role="status">{{ status }} <button class="btn-ghost" type="button" @click="refreshStatus">Try again</button></div>
    <div class="workspace-grid">
      <section class="composer panel"><div class="section-eyebrow">YOUR STUDIO</div><h1>Imagine something new.</h1><p class="studio-hint">Create an original image or transform a reference, privately.</p>
        <div class="mode-tabs" role="group" aria-label="Image mode"><button type="button" :class="{selected:role==='create'}" :aria-pressed="role==='create'" :disabled="view.busy" @click="switchRole('create')"><strong>Create</strong><small>From a description</small></button><button type="button" :class="{selected:role==='edit'}" :aria-pressed="role==='edit'" :disabled="view.busy" @click="switchRole('edit')"><strong>Edit</strong><small>From one reference</small></button></div>
        <div v-if="role==='edit'" class="reference-panel"><div class="reference-heading"><label for="reference">Reference image</label><button v-if="reference" class="btn-ghost" type="button" :disabled="view.busy" @click="clearReference">Remove</button></div><img v-if="reference" :src="reference" class="reference-thumb" alt="Selected reference image"><label v-else for="reference" class="reference-empty">＋ Choose one image<br><small>PNG, JPEG or WebP · up to 5 MiB</small></label><input id="reference" :key="referenceVersion" type="file" accept="image/png,image/jpeg,image/webp" :disabled="view.busy" @change="selectReference"></div>
        <div class="prompt-heading"><label for="prompt">{{ role==='edit' ? 'Describe the change' : 'Describe your image' }}</label><span>{{ prompt.length }} / 4000</span></div><textarea id="prompt" v-model="prompt" rows="5" maxlength="4000" :disabled="view.busy" :placeholder="role==='edit' ? 'What would you like to change?' : 'A quiet place, a character, a scene…'" @input="promptChanged()"></textarea>
        <div class="enhance-actions"><button class="btn-ghost" type="button" :disabled="view.busy || enhancement.busy || !prompt.trim()" @click="enhancer.run(prompt,role)">✦ {{ enhancement.original ? 'Try again' : 'Enhance prompt' }}</button><button v-if="enhancement.busy" class="btn-ghost" type="button" @click="enhancer.cancel()">Cancel enhancement</button><button v-if="enhancement.original" class="btn-ghost" type="button" @click="enhancer.restore()">Restore original</button></div>
        <div v-if="enhancement.suggestion" class="suggestion"><label for="suggestion">Suggested prompt · editable</label><textarea id="suggestion" :value="enhancement.suggestion" rows="4" maxlength="4000" @input="enhancer.edit(($event.target as HTMLTextAreaElement).value)"></textarea><button class="btn-secondary" type="button" :disabled="view.busy || !enhancement.suggestion.trim()" @click="enhancer.accept()">{{ enhancement.accepted ? 'Suggestion applied' : 'Use suggestion' }}</button></div><p v-if="enhancement.error" role="alert" class="studio-error">{{ enhancement.error }}</p>
        <button v-if="!view.busy" class="btn generate-button" type="button" :disabled="!available || enhancement.busy" @click="generate">{{ role==='create' ? '✦  Create preview' : '✦  Edit preview' }}</button><button v-else class="btn-danger generate-button" type="button" :disabled="!view.job || view.phase==='cancelling'" @click="controller.cancel()">{{ view.phase==='cancelling' ? 'Cancelling…' : 'Cancel generation' }}</button>
        <div v-if="view.job" class="job-line" role="status"><StatusChip :status="view.job.state==='running' ? 'generating' : view.job.state" :label="view.phase==='retrieving' ? 'Retrieving result' : view.job.state"/><span v-if="view.job.message">{{ view.job.message }}</span></div><button v-if="view.retry" class="btn-ghost" type="button" @click="controller.retry()">{{ view.retry==='result' ? 'Retry result' : 'Retry job status' }}</button><p v-if="error || view.error" role="alert" class="studio-error">{{ error || view.error }}</p><p class="privacy-note">Preview first. Only Save keeps an image in this browser.</p>
      </section>
      <section class="output-stage preview-panel" aria-label="Image preview"><div class="preview-heading"><div><span class="section-eyebrow">YOUR CANVAS</span><h2>{{ previewReference && resultUrl ? 'Before & after' : 'Preview' }}</h2></div><small v-if="previewItem?.mock">SYNTHETIC MOCK</small></div><div class="compare" :class="{paired:previewReference && resultUrl}"><figure v-if="previewReference && resultUrl"><img :src="previewReference" alt="Original reference"><figcaption>Reference</figcaption></figure><figure v-if="resultUrl"><img :src="resultUrl" alt="Generated preview"><figcaption>{{ previewReference ? 'Edited preview' : 'Generated preview' }}</figcaption></figure><div v-else class="preview-empty"><span aria-hidden="true">✧</span><strong>Your preview will appear here</strong><p>Describe an image to get started.</p></div></div><div v-if="resultUrl" class="preview-actions"><button class="btn" type="button" :disabled="!storageReady || saving || saved || view.busy" @click="savePreview">{{ saved ? '✓ Saved' : saving ? 'Saving…' : 'Save to gallery' }}</button><button v-if="previewItem" class="btn-secondary" type="button" @click="downloadImage(previewItem)">Download</button></div></section>
    </div>
    <section class="gallery-section" aria-label="Browser gallery"><div class="gallery-heading"><div><span class="section-eyebrow">KEPT ON THIS DEVICE</span><h2>Your gallery</h2><p class="studio-hint">Only you choose what to save. No automatic synchronization.</p></div><div class="gallery-tools"><button class="btn-secondary" type="button" :disabled="!storageReady" @click="exportImages">Export</button><label class="btn-secondary import-control">Import<input type="file" accept="application/json,.json" :disabled="!storageReady || importing" @change="importImages"></label></div></div><p class="privacy-note">Up to 50 images · 5 MiB per image · 100 MiB per archive</p><p v-if="galleryError" role="alert" class="studio-error">{{ galleryError }}</p><p v-if="galleryMessage" role="status">{{ galleryMessage }}</p><p v-if="storageReady && !gallery.length" class="gallery-empty">Your saved images will appear here.</p><button v-if="!storageReady" class="btn-secondary" type="button" @click="refreshGallery">Retry storage</button><div class="gallery-grid"><article v-for="entry in gallery" :key="entry.item.id" class="gallery-item"><img :src="entry.url" alt="Saved gallery image"><div class="gallery-item-body"><p>{{ entry.item.role }} <span v-if="entry.item.mock">· synthetic mock</span></p><small>{{ entry.item.createdAt }}</small><p v-if="entry.item.referenceId" class="lineage">Reference: {{ entry.item.referenceId }}</p><div class="gallery-actions"><button class="btn-ghost" type="button" @click="downloadImage(entry.item)">Download</button><button class="btn-ghost" type="button" :disabled="view.busy" @click="reuseImage(entry.item)">Use as reference</button><button class="btn-ghost" type="button" @click="removeImage(entry.item)">Delete</button></div></div></article></div></section>
  </main>
</template>
<style scoped>
.studio-frame{max-width:1500px;margin:auto;padding:16px 8px 56px;color:var(--text);gap:0}.studio-brand strong{display:block;font-size:16px}.studio-brand small{display:block;font-size:9px;letter-spacing:.14em;color:var(--muted)}.brand-mark{display:grid;place-items:center;width:38px;height:38px;border-radius:12px;background:var(--primary);color:var(--primary-text);font-size:22px}.mock-banner,.notice{margin-top:14px;padding:10px 14px;border:1px solid var(--border);border-radius:10px;color:var(--muted);font-size:13px}.workspace-grid{display:grid;grid-template-columns:minmax(300px,430px) minmax(0,1fr);gap:28px;margin-top:28px;align-items:start}.panel{background:var(--panel);border:1px solid var(--border);border-radius:var(--radius-lg);padding:24px;box-shadow:var(--shadow)}.composer{display:grid;gap:12px}.composer h1,.preview-heading h2,.gallery-heading h2{margin:0;letter-spacing:-.025em}.composer h1{font-size:25px}.section-eyebrow{font-size:10px;letter-spacing:.13em;color:var(--muted);font-weight:700}.studio-hint,.privacy-note{color:var(--muted);font-size:13px;margin:0}.mode-tabs{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:6px 0}.mode-tabs button{background:var(--panel-subtle);color:var(--text);border:1px solid var(--border);border-radius:12px;padding:12px;text-align:left;cursor:pointer}.mode-tabs button.selected{border-color:var(--text);box-shadow:0 0 0 1px var(--text)}.mode-tabs small,.reference-empty small{display:block;color:var(--muted);font-size:12px}.prompt-heading,.reference-heading,.gallery-heading,.preview-heading{display:flex;justify-content:space-between;align-items:center;gap:12px}.prompt-heading span{color:var(--muted);font-size:12px}.composer textarea{width:100%;resize:vertical;background:var(--input-bg);color:var(--text);border:1px solid var(--border-strong);border-radius:12px;padding:12px;font:inherit}.enhance-actions,.gallery-tools,.gallery-actions,.preview-actions{display:flex;gap:8px;flex-wrap:wrap}.suggestion{display:grid;gap:8px;padding:12px;background:var(--panel-subtle);border:1px solid var(--border);border-radius:12px}.reference-panel{display:grid;gap:8px}.reference-panel input{max-width:100%}.reference-thumb{width:100%;height:150px;object-fit:contain;border-radius:10px;background:var(--checker-bg)}.reference-empty{border:1px dashed var(--border-strong);border-radius:12px;padding:18px;text-align:center;cursor:pointer}.generate-button{width:100%;min-height:44px}.job-line{display:flex;align-items:center;gap:8px;flex-wrap:wrap;font-size:12px}.studio-error{color:var(--danger);overflow-wrap:anywhere}.preview-panel{display:flex;flex-direction:column;align-items:stretch;justify-content:flex-start;width:100%;padding:8px 0;gap:14px}.preview-heading small{color:var(--muted)}.compare{display:grid;grid-template-columns:1fr;gap:12px;min-height:360px}.compare.paired{grid-template-columns:1fr 1fr}.compare figure{margin:0;display:grid;gap:6px;align-content:center}.compare img{width:100%;max-height:570px;object-fit:contain;border-radius:16px;background:var(--checker-bg)}.compare figcaption{font-size:12px;color:var(--muted)}.preview-empty{display:grid;place-content:center;text-align:center;min-height:360px;border:1px dashed var(--border-strong);border-radius:16px;background:var(--panel-subtle);color:var(--muted)}.preview-empty span{font-size:52px}.preview-empty p{font-size:13px}.preview-actions{justify-content:flex-end}.gallery-section{margin-top:44px;border-top:1px solid var(--border);padding-top:26px}.gallery-heading{align-items:end;flex-wrap:wrap}.import-control{cursor:pointer}.import-control input{max-width:190px;font-size:11px}.gallery-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:16px;margin-top:18px}.gallery-item{border:1px solid var(--border);border-radius:14px;overflow:hidden;background:var(--panel)}.gallery-item img{width:100%;height:180px;object-fit:cover;display:block}.gallery-item-body{padding:12px;overflow-wrap:anywhere}.gallery-item-body p{margin:0}.gallery-item-body small,.lineage{color:var(--muted);font-size:11px}.gallery-actions{margin-top:8px}.gallery-empty{padding:28px 0;color:var(--muted)}@media(max-width:800px){.workspace-grid{grid-template-columns:1fr}.compare{min-height:240px}.preview-empty{min-height:240px}}@media(max-width:480px){.studio-frame{padding:8px 0 32px}.panel{padding:18px}.compare.paired{grid-template-columns:1fr}.gallery-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.gallery-item img{height:130px}}
</style>
